from src.invoice import tax


def test_invoice_tax():
    # Finance policy FIN-12: tax is rounded half up to the cent.
    assert tax(112.50, 0.09) == 10.13


def test_invoice_tax_rounds_below_half_cent_down():
    assert tax(112.49, 0.09) == 10.12


def test_invoice_tax_rounds_above_half_cent_up():
    assert tax(112.51, 0.09) == 10.13


def test_invoice_tax_rounds_negative_half_cent_away_from_zero():
    assert tax(-112.50, 0.09) == -10.13

